ext-secondary py-5">Belum ada data pada periode ini.</td></tr><?php endif;?></tbody><tfoot><?php if($report['rows']):?><tr><th class="text-start">TOTAL</th><?php foreach($report['columns'] as $column):foreach($report['splits'] as $split):?><th><?=number_format((int)($report['column_totals'][$column][$split]??0),0,',','.');?></th><?php endforeach;endforeach;?><?php foreach($report['splits'] as $split):?><th class="bg-blue-lt"><?=number_format((int)($report['split_totals'][$split]??0),0,',','.');?></th><?php endforeach;?></tr><?php endif;?></tfoot></table></div></div></div></div>
<style>.custom-report-table thead th{vertical-align:middle;white-space:nowrap}.custom-report-table td{min-width:48px}.custom-report-table td:first-child{min-width:125px;position:sticky;left:0;background:#fff;z-index:1}</style><script>(function(){var mode=document.getElementById('format-mode');function sync(){document.querySelectorAll('.format-period').forEach(function(x){x.style.display='none'});document.querySelectorAll('.format-'+mode.value).forEach(function(x){x.style.display=''})}mode.addEventListener('change',sync);sync()})();</script>
